D=[
# ---------- witness_reliability ----------
("witness_reliability","شاهد في لغز خيالي يصف شخصاً رآه لثوانٍ في ليل مظلم، ويجزم بأنه سيعرفه بين مئة.","كيف تقيّم ثقته العالية؟",
 ["الثقة العالية دليل على الدقة","الثقة لا تقيس الدقة؛ أنظر إلى الإضاءة والمدة والمسافة وما إذا كان وصفه موثقاً قبل أي عرض صور","أرفض شهادته لأنه شاهد وحيد"],1,
 "شعور الشاهد باليقين لا يرتبط ارتباطاً مضموناً بصحة الذاكرة. نفحص ظروف المشاهدة ونسجل الوصف مبكراً، ولا نرفض الشهادة بالكامل بل نزنها.","ثقة الشاهد"),
("witness_reliability","عُرضت على شاهدين صورة واحدة فقط لمشتبه به، وسئلا: هل هو هذا؟","ما المشكلة في الإجراء؟",
 ["لا مشكلة لأن الصورة واضحة","عرض صورة واحدة يوحي بالجواب؛ الأفضل مجموعة متشابهة مع تعليمات محايدة","المشكلة أن الصورة ملونة"],1,
 "الإيحاء يرفع احتمال الاختيار الخاطئ. مجموعة الصور المتشابهة وتعليمات تقول إن الفاعل قد لا يكون موجوداً تحسّنان الموثوقية.","عرض الصور"),
("witness_reliability","شاهد غيّر روايته بعد أن قرأ الخبر في الصحف.","كيف تفسر ذلك؟",
 ["كذب بالتأكيد","قد تتأثر الذاكرة بمعلومات لاحقة، لذا أعتمد روايته الأولى المسجلة وأسجل التغير دون اتهام","أعتمد الرواية الأحدث دائماً"],1,
 "المعلومات اللاحقة قد تختلط بالذاكرة دون سوء نية. الرواية الأولى المسجلة أقرب للأصل، والتغير يُوثَّق ويُسأل عنه.","تلوث الذاكرة"),
("witness_reliability","سيدة تشهد بأنها رأت سيارة حمراء، وأخرى بأنها زرقاء، والإضاءة صفراء.","ما الخطوة المنطقية؟",
 ["أختار الأكبر سناً","أختبر كيف يظهر اللونان تحت تلك الإضاءة، وأبحث عن دليل مادي مستقل","أستنتج أن إحداهما تكذب"],1,
 "الإضاءة تغير إدراك الألوان. الخلاف لا يعني كذباً، ويُحسم بقياس أو بدليل مستقل.","ظروف الرؤية"),
("witness_reliability","شاهد يقول إنه رأى كل شيء بتفاصيل كثيرة غريبة لم يذكرها أحد غيره.","ما موقفك؟",
 ["أصدق التفاصيل الإضافية لأنها كثيرة","أتحقق من إمكان رؤيته لها فعلاً وأقارنها بأدلة مادية، فالتفاصيل الكثيرة ليست برهاناً بذاتها","أعتبره كاذباً"],1,
 "الذاكرة قد تملأ الفراغات بتفاصيل معقولة. نختبر قابلية التفاصيل للتحقق من مصدر آخر.","تفاصيل"),
("witness_reliability","طُلب من طفل خيالي أن يصف ما حدث، وكان المحقق يعيد صياغة السؤال موجهاً نحو جواب معين.","ما الأفضل؟",
 ["الاستمرار حتى يعطي الجواب المطلوب","أسئلة مفتوحة محايدة، وتسجيل ما قاله بكلماته، وعدم تكرار السؤال بصيغ موحية","إنهاء المقابلة وتجاهل كلامه"],1,
 "الأسئلة الموحية تلوث الإفادة، خصوصاً مع الصغار. المقابلة المفتوحة تحفظ أصالة الرواية.","أسئلة موحية"),
("witness_reliability","شاهد له مصلحة مالية في نتيجة القضية يقدم رواية تتفق مع مصلحته.","كيف تتعامل مع روايته؟",
 ["أرفضها لأن له مصلحة","أسجلها وأبحث عما يؤيدها أو يخالفها من مصادر مستقلة، وأذكر المصلحة صراحة في التقرير","أقبلها لأنها متسقة"],1,
 "المصلحة لا تعني الكذب، لكنها سبب لطلب تأييد مستقل. الإفصاح عنها جزء من الشفافية.","مصلحة الشاهد"),
("witness_reliability","اتفق ثلاثة شهود على رواية، واكتُشف أنهم تحدثوا معاً قبل المقابلة.","ما أثر ذلك؟",
 ["يقوي الرواية لأن الاتفاق كامل","يضعف استقلال شهاداتهم، فالاتفاق بعد التشاور لا يعد تأييداً مستقلاً","لا أثر"],1,
 "قيمة الشهادة المتعددة في استقلالها. التشاور قد ينشر خطأ واحداً بين الجميع.","استقلال الشهود"),
("witness_reliability","قال شاهد: «سمعت صوت ارتطام ثم رأيت الرجل يجري». لم يذكر ما رآه قبل الصوت.","ماذا تسأل؟",
 ["هل يظن أن الرجل مذنب؟","ماذا كان يفعل لحظة سمع الصوت، وأين كان واقفاً، وما الذي كان يحجب الرؤية؟","هل يعرف الرجل؟"],1,
 "نتحقق من موقع الشاهد وحاسّته وما يحجبه. السؤال عن الظن يدعو إلى رأي لا ملاحظة.","موقع الشاهد"),
("witness_reliability","شاهد يتردد ويصحح نفسه كثيراً في روايته.","كيف تقرأ ذلك؟",
 ["التردد دليل كذب","التردد وحده لا يدل على شيء؛ يُقارن بسلوكه المعتاد وبمطابقة روايته للأدلة","التردد دليل صدق"],1,
 "الدلائل السلوكية ضعيفة في الحكم على الصدق. المقارنة بالوقائع المستقلة أنفع.","سلوك"),
("witness_reliability","اعترف شخص خيالي في المقابلة الأولى بتفاصيل لم تتأكد، وكان متعباً جداً بعد ساعات طويلة.","ما أنسب تعامل؟",
 ["اعتراف مكتمل لا يحتاج شيئاً","يُقارن الاعتراف بالأدلة المادية، وتُفحص ظروف أخذه، وأبحث عن تفاصيل لا يعرفها إلا الفاعل","أتجاهل الاعتراف"],1,
 "الاعتراف يحتاج إلى تأييد مادي مستقل، وظروف الإرهاق تستدعي الحذر. والتجاهل التام إفراط.","اعتراف"),
# ---------- lab_limits ----------
("lab_limits","أظهر فحص مخبري خيالي وجود أثر مادة على قطعة قماش.","ما الذي يمكن قوله بأمان؟",
 ["أن المادة هي سبب الحادث","أن الأثر وُجد على القماش، وأن دلالته على الحادث تحتاج إلى سياق ومقارنة وزمن","لا شيء على الإطلاق"],1,
 "الوجود لا يثبت السبب ولا الزمن. المختبر يخبرنا ما وُجد، والباقي استدلال يُبنى عليه بحذر.","وجود الأثر"),
("lab_limits","نتيجة فحص تقول: «متوافق مع» عينة من مشتبه.","ما معنى التوافق؟",
 ["أنه الفاعل بالتأكيد","أن العينتين لا يختلفان في الصفات المفحوصة، وقد يشترك فيها آخرون بنسبة تحتاج إلى بيانها","أنه بريء"],1,
 "التوافق ليس هوية. قوته تعتمد على ندرة الصفات في المجتمع وعلى جودة العينة.","التوافق"),
("lab_limits","عينة قديمة تعرضت للحرارة والرطوبة قبل وصولها إلى المختبر.","كيف تؤثر في التفسير؟",
 ["لا تؤثر","قد تتدهور فتصبح النتيجة غير حاسمة أو مضللة، ويجب ذكر ظروف الحفظ مع النتيجة","تصبح أقوى"],1,
 "التلف قد يخلق نتائج زائفة أو يمحو حقيقية. الإفصاح عن ظروف الحفظ جزء من معنى النتيجة.","حفظ العينة"),
("lab_limits","طلب القاضي الخيالي جواباً بنعم أو لا، والنتيجة تقول إن الاحتمال مرجح لكنه غير مؤكد.","ما أفضل رد؟",
 ["نعم","أقدم درجة الترجيح وحدودها بلغة واضحة دون تحويلها إلى يقين","لا"],1,
 "الاختزال إلى نعم أو لا يضلل. الأمانة في بيان درجة اليقين وحدود الفحص.","درجات اليقين"),
("lab_limits","مقارنة بين أثرين تمت بالعين المجردة فقط ثم صرّح المحلل بأنهما من المصدر نفسه.","ما المشكلة؟",
 ["لا مشكلة","التشابه البصري لا يكفي؛ المقارنة تحتاج منهجاً موثقاً وقياساً وتحققاً مستقلاً","المشكلة في اللون"],1,
 "الانطباع البصري عرضة للانحياز. الأساليب الموثقة والمراجعة المستقلة تقلل الخطأ.","مقارنة"),
("lab_limits","كان المحلل يعرف مسبقاً أن الشرطة تشتبه في شخص بعينه حين قارن العينات.","ما الخطر؟",
 ["لا خطر","قد يميل التفسير إلى ما يتوقعه، فتُفضَّل المراجعة الأعمى أو إخفاء المعلومات غير اللازمة","الخطر في جهاز المختبر"],1,
 "تأثير التوقع قد يغير القراءة. إخفاء السياق غير الضروري يخفض الانحياز.","انحياز التوقع"),
("lab_limits","اختبار أولي سريع أعطى نتيجة إيجابية.","كيف تصنف النتيجة؟",
 ["نهائية","أولية تحتاج إلى تأكيد بفحص أدق، لأن الاختبارات السريعة قد تعطي نتائج زائفة","لا قيمة لها إطلاقاً"],1,
 "الاختبارات الأولية للفرز لا للحسم. والتأكيد جزء من المنهج.","اختبار أولي"),
("lab_limits","تقرير خيالي يذكر أن احتمال وقوع التطابق بالصدفة صغير جداً.","ما السؤال الذي تسأله؟",
 ["هل الرقم كبير؟","على أي قاعدة بيانات حُسب الاحتمال، وهل تمثل المجتمع الذي ينتمي إليه المشتبه؟","هل خط التقرير جميل؟"],1,
 "الاحتمال يتوقف على التعداد المرجعي. قاعدة غير ممثلة تعطي أرقاماً مضللة.","احتمال"),
("lab_limits","وجدت بصمة أصبع جزئية على سطح، ويقول المحلل إنها لا تطابق إلا فلاناً.","كيف تتعامل مع القول؟",
 ["أقبله فالبصمات فريدة دائماً","أسأل عن حجم الجزء الظاهر وعدد النقاط ومراجعة مستقلة، فالجزئية أقل قطعية وهناك احتمال خطأ","أرفضه لأن البصمات غير موثوقة"],1,
 "الادعاء بتفرد مطلق يتجاوز ما أثبته البحث. البصمة الجزئية أضعف، وللمراجعة المستقلة قيمة.","بصمة جزئية"),
("lab_limits","فحص خط يد لعينتين أعطى «تشابهاً كبيراً» لكن العينة المقارنة كانت قصيرة جداً.","ما الصياغة الأنسب؟",
 ["مطابقة قاطعة","تشابه مع ذكر أن قصر العينة يحد من قوة الحكم، وربما رأي احتمالي","عدم تطابق"],1,
 "كمية المادة المتاحة للمقارنة تحدد قوة الحكم. الصياغة الاحتمالية أمينة.","فحص الخط"),
("lab_limits","نتيجة مخبرية تتعارض مع شهادة شاهد.","ما أنسب طريقة للتعامل؟",
 ["أصدق المختبر دائماً","أبحث عن أسباب محتملة للتعارض في كل منهما، مثل خطأ إدراك أو تلوث أو سوء تفسير، ثم أطلب أدلة إضافية","أصدق الشاهد دائماً"],1,
 "لا مصدر معصوم. التعارض يدعو إلى فحص مصادر الخطأ لا إلى الانحياز لأحد الطرفين.","تعارض"),
# ---------- reporting ----------
("reporting","ستكتب فقرة الخلاصة في تقرير. وصلتك أدلة متفاوتة القوة.","ما الأسلوب المناسب؟",
 ["أكتب النتيجة الأقوى فقط","أصنف الاستنتاجات بحسب قوة الدليل، وأذكر ما لا يمكن الجزم به وما قد يغيّر الرأي","أكتب ما يرضي المدير"],1,
 "التقرير الجيد يفصل بين المثبت والمرجح والمجهول. إخفاء الحدود يعطي صورة أقوى من الحقيقة.","درجة اليقين"),
("reporting","ظهر لك احتمال ثانٍ ضعيف لا يؤيد رأيك الأول.","هل تذكره؟",
 ["لا، لأنه يربك القارئ","نعم، مع بيان لماذا هو أضعف وما الذي يستبعده أو لا يستبعده","فقط إن سأل أحد"],1,
 "ذكر البدائل يمنح القارئ فرصة للحكم ويحمي من انحياز التأكيد.","البدائل"),
("reporting","كتب زميلك: «المتهم هو الفاعل». ولم يكن لديكم سوى أثر واحد غير حاسم.","كيف تعدّل الجملة؟",
 ["أبقيها","أعيد صياغتها: «الأثر المفحوص لا يستبعد صلة فلان بالمشهد، ولا يكفي وحده لإثباتها»","أحذف الأثر"],1,
 "الاستنتاج يجب ألا يتجاوز الدليل. والصياغة المحايدة تحفظ مقام العلم والعدالة.","تجاوز الدليل"),
("reporting","تريد أن تعرض الخط الزمني للأحداث.","ما الأفضل؟",
 ["سرد قصة متصلة من دون مصادر","جدول يربط كل حدث بمصدره ودرجة موثوقيته، مع تمييز المعروف من المقدَّر","رسم بلا تواريخ"],1,
 "ربط الحدث بمصدره يتيح التحقق. والتمييز بين المعروف والمقدر يمنع الخلط.","الخط الزمني"),
("reporting","قيل لك: «اكتب التقرير بما يناسب النيابة». لا تعرف الصيغة التي تريدها.","ماذا تفعل؟",
 ["أكتب ما أتوقعه أنهم يريدونه","ألتزم بالوقائع والمنهج والحدود وبنية التقرير المعتمدة، ولا أعدّل الاستنتاج ليناسب أحداً","لا أكتب شيئاً"],1,
 "الاستقلال المهني يعني أن الاستنتاج يتبع الدليل لا رغبة الطالب.","استقلال الخبير"),
("reporting","في تقريرك مصطلح تقني لن يفهمه القارئ العادي.","ما التصرف؟",
 ["أتركه فهو دقيق","أشرحه في سطر بلغة بسيطة دون أن أغيّر المعنى","أحذفه"],1,
 "الوضوح جزء من الأمانة. والشرح المختصر لا يخل بالدقة.","وضوح اللغة"),
("reporting","اكتشفت بعد تسليم التقرير خطأً في رقم قياس.","ما الواجب؟",
 ["أنتظر ليكتشفه غيري","أبلغ المعنيين فوراً وأصدر تصحيحاً موثقاً يبين ما تغير","أصلحه دون إخبار أحد"],1,
 "الاعتراف بالخطأ وتوثيق التصحيح يحميان سلامة القضية والثقة بالمنهج.","تصحيح"),
("reporting","طُلب منك رأي خارج تخصصك في موضوع قريب.","كيف تتصرف؟",
 ["أجيب بثقة","أصرح بحدود تخصصي وأحيل إلى المختص","أخمّن وأغطي ذلك بعبارات عامة"],1,
 "الخبرة محدودة بميدانها. التصريح بالحدود جزء من الأمانة العلمية.","حدود الخبرة"),
("reporting","تريد أن تُدرج ما فعلته خطوة بخطوة ليعيد غيرك العمل.","أي عنصر أهم؟",
 ["الأسلوب الأدبي","المنهج والأدوات والظروف وما لوحظ بدقة، بحيث يمكن التكرار والتحقق","الاستنتاج فقط"],1,
 "قابلية التكرار تجعل العمل علمياً. الاستنتاج بلا منهج لا يمكن فحصه.","قابلية التكرار"),
("reporting","كتب محرر صحفي عنواناً يقول: «العلم يثبت أن فلاناً مذنب» اعتماداً على تقريرك الذي لم يقل ذلك.","ما التصرف المناسب؟",
 ["أسكت","أطلب تصحيح العنوان وأوضح ما يدعمه التقرير وما لا يدعمه","أتبنى العنوان"],1,
 "تقارير العلم تُسيء فهمها وسائل الإعلام أحياناً. التوضيح العلني يحمي دقة المعنى.","تواصل"),
("reporting","قارنت بين نسختين من الملف فوجدت اختلافاً في فقرة واحدة دون توضيح لسببه.","ما الإجراء؟",
 ["أعتمد الأحدث","أعتمد النسخة الموثقة وأسأل عن سبب التغيير وأسجل الفرق في سجل التعديلات","أحذف الفقرة"],1,
 "سجل التعديلات يحفظ مسؤولية كل تغيير. والحذف يخفي الدليل على التغيير.","سجل تعديلات"),
("reporting","لخصت قضية خيالية لطلاب، وأردت أن تذكر الدرس.","ما أفضل صيغة؟",
 ["هذه الحالة تثبت أن كل الشهود كاذبون","من هذه الحالة نتعلم أن نفصل الوصف عن التفسير وأن نبحث عن مصدر مستقل قبل الحكم","لا درس"],1,
 "الدرس العام المحدود أفضل من حكم شامل غير مبرر.","درس"),
]
